PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS file_assets (id TEXT PRIMARY KEY, sha256 TEXT NOT NULL CHECK(length(sha256)=64), original_path TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK(byte_size>=0), managed_copy INTEGER NOT NULL DEFAULT 0 CHECK(managed_copy IN(0,1)), media_type TEXT NOT NULL DEFAULT 'application/pdf', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_asset_sha ON file_assets(sha256);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), title TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted_at TEXT);
CREATE INDEX IF NOT EXISTS idx_document_ws ON documents(workspace_id);
CREATE TABLE IF NOT EXISTS document_versions (id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), file_asset_id TEXT NOT NULL REFERENCES file_assets(id), version_no INTEGER NOT NULL CHECK(version_no>=1), revision_label TEXT, status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','PROCESSING','READY','PARTIAL','FAILED','MISSING')), extraction_generation INTEGER NOT NULL DEFAULT 0, parser_version TEXT, ocr_engine TEXT, extraction_params_hash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(document_id,version_no));
CREATE INDEX IF NOT EXISTS idx_dv_doc ON document_versions(document_id);
CREATE TABLE IF NOT EXISTS pages (id TEXT PRIMARY KEY, document_version_id TEXT NOT NULL REFERENCES document_versions(id), page_index INTEGER NOT NULL CHECK(page_index>=0), page_label TEXT, width REAL NOT NULL CHECK(width>0), height REAL NOT NULL CHECK(height>0), rotation INTEGER NOT NULL DEFAULT 0, coordinate_system TEXT NOT NULL DEFAULT 'pdf_points', ocr_status TEXT NOT NULL DEFAULT 'NOT_NEEDED', UNIQUE(document_version_id,page_index));
CREATE TABLE IF NOT EXISTS content_blocks (id TEXT PRIMARY KEY, page_id TEXT NOT NULL REFERENCES pages(id), block_index INTEGER NOT NULL, block_type TEXT NOT NULL, text TEXT NOT NULL DEFAULT '', bbox_json TEXT NOT NULL CHECK(json_valid(bbox_json)), reading_order INTEGER NOT NULL, confidence REAL CHECK(confidence BETWEEN 0 AND 1), extraction_generation INTEGER NOT NULL DEFAULT 0, UNIQUE(page_id,block_index,extraction_generation));
CREATE INDEX IF NOT EXISTS idx_blocks_page ON content_blocks(page_id);
CREATE VIRTUAL TABLE IF NOT EXISTS content_blocks_fts USING fts5(text, content='content_blocks', content_rowid='rowid', tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER IF NOT EXISTS blocks_ai AFTER INSERT ON content_blocks BEGIN INSERT INTO content_blocks_fts(rowid,text) VALUES(new.rowid,new.text); END;
CREATE TRIGGER IF NOT EXISTS blocks_ad AFTER DELETE ON content_blocks BEGIN INSERT INTO content_blocks_fts(content_blocks_fts,rowid,text) VALUES('delete',old.rowid,old.text); END;
CREATE TRIGGER IF NOT EXISTS blocks_au AFTER UPDATE ON content_blocks BEGIN INSERT INTO content_blocks_fts(content_blocks_fts,rowid,text) VALUES('delete',old.rowid,old.text); INSERT INTO content_blocks_fts(rowid,text) VALUES(new.rowid,new.text); END;
CREATE TABLE IF NOT EXISTS chunks (id TEXT PRIMARY KEY, document_version_id TEXT NOT NULL REFERENCES document_versions(id), text TEXT NOT NULL, chunk_index INTEGER NOT NULL, block_ids_json TEXT NOT NULL CHECK(json_valid(block_ids_json)), chunker_version TEXT NOT NULL, extraction_generation INTEGER NOT NULL, UNIQUE(document_version_id,chunk_index,extraction_generation));
CREATE TABLE IF NOT EXISTS extracted_tables (id TEXT PRIMARY KEY, page_id TEXT NOT NULL REFERENCES pages(id), table_index INTEGER NOT NULL, bbox_json TEXT NOT NULL CHECK(json_valid(bbox_json)), extraction_generation INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS table_cells (id TEXT PRIMARY KEY, table_id TEXT NOT NULL REFERENCES extracted_tables(id), row_index INTEGER NOT NULL, col_index INTEGER NOT NULL, row_span INTEGER NOT NULL DEFAULT 1, col_span INTEGER NOT NULL DEFAULT 1, text TEXT NOT NULL DEFAULT '', bbox_json TEXT NOT NULL CHECK(json_valid(bbox_json)), confidence REAL CHECK(confidence BETWEEN 0 AND 1), UNIQUE(table_id,row_index,col_index));
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, document_version_id TEXT REFERENCES document_versions(id), kind TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED')), attempts INTEGER NOT NULL DEFAULT 0, error_code TEXT, detail TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS model_registry (id TEXT PRIMARY KEY, provider TEXT NOT NULL, model_name TEXT NOT NULL, digest TEXT, role TEXT NOT NULL, config_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(config_json)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversations (id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id), title TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS analysis_runs (id TEXT PRIMARY KEY, conversation_id TEXT REFERENCES conversations(id), mode TEXT NOT NULL CHECK(mode IN('EVIDENCE_ONLY','REASONING')), model_id TEXT REFERENCES model_registry(id), source_versions_json TEXT NOT NULL CHECK(json_valid(source_versions_json)), prompt_version TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), analysis_run_id TEXT REFERENCES analysis_runs(id), role TEXT NOT NULL CHECK(role IN('USER','ASSISTANT','SYSTEM')), content TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS claims (id TEXT PRIMARY KEY, analysis_run_id TEXT NOT NULL REFERENCES analysis_runs(id), kind TEXT NOT NULL CHECK(kind IN('SOURCE_FACT','INFERENCE','UNKNOWN')), claim_text TEXT NOT NULL, support_status TEXT NOT NULL DEFAULT 'UNREVIEWED', reasoning_summary TEXT);
CREATE TABLE IF NOT EXISTS citations (id TEXT PRIMARY KEY, claim_id TEXT NOT NULL REFERENCES claims(id), document_version_id TEXT NOT NULL REFERENCES document_versions(id), page_id TEXT NOT NULL REFERENCES pages(id), block_id TEXT NOT NULL REFERENCES content_blocks(id), quote TEXT NOT NULL, verification_status TEXT NOT NULL DEFAULT 'UNRESOLVED' CHECK(verification_status IN('VERIFIED_ANCHOR','UNRESOLVED','INVALID')), bbox_json TEXT NOT NULL CHECK(json_valid(bbox_json)));
CREATE INDEX IF NOT EXISTS idx_citations_claim ON citations(claim_id);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, event_type TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, event_json TEXT NOT NULL CHECK(json_valid(event_json)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS audit_immutable_update BEFORE UPDATE ON audit_logs BEGIN SELECT RAISE(ABORT,'audit_log append-only'); END;
CREATE TRIGGER IF NOT EXISTS audit_immutable_delete BEFORE DELETE ON audit_logs BEGIN SELECT RAISE(ABORT,'audit_log append-only'); END;
INSERT OR IGNORE INTO schema_migrations(version) VALUES(1);
